WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY pressure DESC NULLS LAST, id) AS latest_rank FROM device_readings) x WHERE latest_rank = 1) SELECT CASE WHEN status_bits >= 11 THEN 'HIGH' ELSE 'LOW' END AS status_bits_tier, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list_2, COUNT_IF(device_code = 'DV-01') AS dv_01_events FROM ranked GROUP BY CASE WHEN status_bits >= 11 THEN 'HIGH' ELSE 'LOW' END;
